#include <bits/stdc++.h>
using namespace std;

string in;
size_t pos_ = 0;

static void pushUnit(string& key, unsigned unit) { key += char(unit >> 8); key += char(unit & 255); }

// Decodes a JSON string starting at the opening quote into a key of UTF-16 code units,
// so escaped and raw spellings of the same text compare equal.
string readString() {
    string key;
    pos_++;
    while (in[pos_] != '"') {
        unsigned char c = in[pos_];
        if (c == '\\') {
            char e = in[pos_ + 1];
            pos_ += 2;
            switch (e) {
                case 'b': pushUnit(key, 8); break;
                case 'f': pushUnit(key, 12); break;
                case 'n': pushUnit(key, 10); break;
                case 'r': pushUnit(key, 13); break;
                case 't': pushUnit(key, 9); break;
                case 'u': pushUnit(key, stoul(in.substr(pos_, 4), nullptr, 16)); pos_ += 4; break;
                default: pushUnit(key, (unsigned char)e);
            }
            continue;
        }
        unsigned cp; int len;
        if (c < 0x80) cp = c, len = 1;
        else if (c < 0xE0) cp = c & 0x1F, len = 2;
        else if (c < 0xF0) cp = c & 0x0F, len = 3;
        else cp = c & 0x07, len = 4;
        for (int i = 1; i < len; i++) cp = (cp << 6) | (in[pos_ + i] & 0x3F);
        pos_ += len;
        if (cp >= 0x10000) { cp -= 0x10000; pushUnit(key, 0xD800 + (cp >> 10)); pushUnit(key, 0xDC00 + (cp & 0x3FF)); }
        else pushUnit(key, cp);
    }
    pos_++;
    return key;
}

int main() {
    char chunk[1 << 16];
    for (size_t got; (got = fread(chunk, 1, sizeof chunk, stdin)) > 0;) in.append(chunk, got);
    // Shape: [[tool, ...], startIndex, target].
    vector<string> tools;
    string target;
    long long start = 0;
    int depth = 0;
    while (pos_ < in.size()) {
        char c = in[pos_];
        if (c == '[') depth++, pos_++;
        else if (c == ']') depth--, pos_++;
        else if (c == '"') {
            if (depth == 2) tools.push_back(readString());
            else target = readString();
        } else if (isdigit((unsigned char)c) && depth == 1) {
            start = 0;
            while (pos_ < in.size() && isdigit((unsigned char)in[pos_])) start = start * 10 + (in[pos_++] - '0');
        } else pos_++;
    }
    long long n = tools.size(), answer = n;
    for (long long i = 0; i < n; i++) {
        if (tools[i] == target) {
            long long d = llabs(i - start);
            answer = min({answer, d, n - d});
        }
    }
    printf("%lld\n", answer == n ? -1 : answer);
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {
    static String in;
    static int pos = 0;

    // Decodes a JSON string starting at the opening quote (Java strings are UTF-16 already).
    static String readString() {
        StringBuilder sb = new StringBuilder();
        pos++;
        while (in.charAt(pos) != '"') {
            char c = in.charAt(pos);
            if (c == '\\') {
                char e = in.charAt(pos + 1);
                pos += 2;
                switch (e) {
                    case 'b' -> sb.append('\b');
                    case 'f' -> sb.append('\f');
                    case 'n' -> sb.append('\n');
                    case 'r' -> sb.append('\r');
                    case 't' -> sb.append('\t');
                    case 'u' -> { sb.append((char) Integer.parseInt(in.substring(pos, pos + 4), 16)); pos += 4; }
                    default -> sb.append(e);
                }
            } else {
                sb.append(c);
                pos++;
            }
        }
        pos++;
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        in = new String(System.in.readAllBytes(), StandardCharsets.UTF_8);
        // Shape: [[tool, ...], startIndex, target].
        ArrayList<String> tools = new ArrayList<>();
        String target = "";
        long start = 0;
        int depth = 0;
        while (pos < in.length()) {
            char c = in.charAt(pos);
            if (c == '[') { depth++; pos++; }
            else if (c == ']') { depth--; pos++; }
            else if (c == '"') {
                if (depth == 2) tools.add(readString());
                else target = readString();
            } else if (c >= '0' && c <= '9' && depth == 1) {
                start = 0;
                while (pos < in.length() && in.charAt(pos) >= '0' && in.charAt(pos) <= '9') start = start * 10 + (in.charAt(pos++) - '0');
            } else pos++;
        }
        long n = tools.size(), answer = n;
        for (int i = 0; i < n; i++) {
            if (tools.get(i).equals(target)) {
                long d = Math.abs(i - start);
                answer = Math.min(answer, Math.min(d, n - d));
            }
        }
        System.out.println(answer == n ? -1 : answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"strconv"
	"unicode/utf8"
)

var in []byte
var pos int

func pushUnit(key []byte, unit int) []byte { return append(key, byte(unit>>8), byte(unit)) }

// readString decodes a JSON string starting at the opening quote into a key of UTF-16 code
// units, so escaped and raw spellings of the same text compare equal.
func readString() string {
	key := []byte{}
	pos++
	for in[pos] != '"' {
		c := in[pos]
		if c == '\\' {
			e := in[pos+1]
			pos += 2
			switch e {
			case 'b':
				key = pushUnit(key, 8)
			case 'f':
				key = pushUnit(key, 12)
			case 'n':
				key = pushUnit(key, 10)
			case 'r':
				key = pushUnit(key, 13)
			case 't':
				key = pushUnit(key, 9)
			case 'u':
				v, _ := strconv.ParseUint(string(in[pos:pos+4]), 16, 32)
				key = pushUnit(key, int(v))
				pos += 4
			default:
				key = pushUnit(key, int(e))
			}
			continue
		}
		r, size := utf8.DecodeRune(in[pos:])
		pos += size
		if r >= 0x10000 {
			r -= 0x10000
			key = pushUnit(key, 0xD800+int(r>>10))
			key = pushUnit(key, 0xDC00+int(r&0x3FF))
		} else {
			key = pushUnit(key, int(r))
		}
	}
	pos++
	return string(key)
}

func main() {
	in, _ = io.ReadAll(os.Stdin)
	// Shape: [[tool, ...], startIndex, target].
	tools := []string{}
	target := ""
	start := 0
	depth := 0
	for pos < len(in) {
		c := in[pos]
		switch {
		case c == '[':
			depth++
			pos++
		case c == ']':
			depth--
			pos++
		case c == '"':
			if depth == 2 {
				tools = append(tools, readString())
			} else {
				target = readString()
			}
		case c >= '0' && c <= '9' && depth == 1:
			start = 0
			for pos < len(in) && in[pos] >= '0' && in[pos] <= '9' {
				start = start*10 + int(in[pos]-'0')
				pos++
			}
		default:
			pos++
		}
	}
	n := len(tools)
	answer := n
	for i, name := range tools {
		if name == target {
			d := i - start
			if d < 0 {
				d = -d
			}
			answer = min(answer, d, n-d)
		}
	}
	if answer == n {
		answer = -1
	}
	fmt.Println(answer)
}
